-- Original DatalytIQs CA35P mock. No historical examination text is reproduced.
-- Keys remain in private schema; learner attempts are written through authenticated RPCs.
update public.exam_assessments set title='CA35P Full Online Mock · Evidence and Decision Case',max_attempts=2,metadata=metadata || '{"total_marks":100,"delivery":"timed online assignment with assessor-reviewed practicals"}'::jsonb where assessment_type='mock' and programme_id=(select id from public.exam_programmes where code='CA35P') and status='published';
insert into public.exam_questions(programme_id,syllabus_version_id,topic_id,question_type,stem,options,difficulty,provenance,rights_metadata,status) select a.programme_id,a.syllabus_version_id,t.id,'single_choice','The 12 sales rows sum to KES 958,750. A PivotTable shows KES 882,500 after a new row was appended. Which control should be checked first?','[{"value": "a", "label": "Change the rate assumption"}, {"value": "b", "label": "Refresh and verify the PivotTable source range"}, {"value": "c", "label": "Hide the missing row"}, {"value": "d", "label": "Overwrite the PivotTable total"}]'::jsonb,'intermediate','original',jsonb_build_object('mock_code','M01'),'published' from public.exam_assessments a join public.exam_topics t on t.syllabus_version_id=a.syllabus_version_id and t.code='1.0' where a.assessment_type='mock' and a.programme_id=(select id from public.exam_programmes where code='CA35P') and not exists(select 1 from public.exam_questions q where q.programme_id=a.programme_id and q.rights_metadata->>'mock_code'='M01');
insert into private.exam_question_keys(question_id,answer_key,explanation) select q.id,jsonb_build_object('correct_option','b'),'Review the source figures and reasoning in the case before retrying.' from public.exam_questions q where q.programme_id=(select id from public.exam_programmes where code='CA35P') and q.rights_metadata->>'mock_code'='M01' on conflict(question_id) do nothing;
