create or replace function public.start_ca35p_mock()
returns uuid language plpgsql security definer set search_path='' as $$
declare v_user uuid:=(select auth.uid()); v_assessment public.exam_assessments%rowtype; v_enrollment uuid; v_attempt uuid; v_count integer;
begin
 if v_user is null then raise exception 'Sign in required'; end if;
 select a.* into v_assessment from public.exam_assessments a join public.exam_programmes p on p.id=a.programme_id where p.code='CA35P' and a.assessment_type='mock' and a.status='published' limit 1;
 if v_assessment.id is null or (select count(*) from public.exam_assessment_items where assessment_id=v_assessment.id)<>25 then raise exception 'Mock assignment is unavailable'; end if;
 select e.id into v_enrollment from public.exam_enrollments e where e.user_id=v_user and e.programme_id=v_assessment.programme_id and e.status='active';
 if v_enrollment is null or not exists(select 1 from public.exam_access_grants g where g.user_id=v_user and g.programme_id=v_assessment.programme_id and g.access_level='full' and g.revoked_at is null and g.starts_at<=now() and (g.expires_at is null or g.expires_at>now())) then raise exception 'Active full programme access required'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_user::text||v_assessment.id::text));
 select id into v_attempt from public.exam_assessment_attempts where assessment_id=v_assessment.id and user_id=v_user and status='in_progress' order by started_at desc limit 1;
 if v_attempt is not null then
   if exists(select 1 from public.exam_assessment_attempts where id=v_attempt and started_at+make_interval(mins=>v_assessment.time_limit_minutes)<=now()) then
     perform public.submit_ca35p_mock(v_attempt); v_attempt:=null;
   else return v_attempt; end if;
 end if;
 select count(*) into v_count from public.exam_assessment_attempts where assessment_id=v_assessment.id and user_id=v_user;
 if v_assessment.max_attempts is not null and v_count>=v_assessment.max_attempts then raise exception 'Maximum attempts reached'; end if;
 insert into public.exam_assessment_attempts(assessment_id,enrollment_id,user_id,attempt_no,integrity_metadata) values(v_assessment.id,v_enrollment,v_user,v_count+1,jsonb_build_object('version','ca35p-original-2026-09')) returning id into v_attempt;
 return v_attempt;
end $$;

create or replace function public.save_ca35p_mock(p_attempt_id uuid,p_responses jsonb)
returns integer language plpgsql security definer set search_path='' as $$
declare v_user uuid:=(select auth.uid()); v_attempt public.exam_assessment_attempts%rowtype; v_item record; v_value text; v_saved integer:=0;
begin
 if v_user is null then raise exception 'Sign in required'; end if;
 select * into v_attempt from public.exam_assessment_attempts where id=p_attempt_id and user_id=v_user and status='in_progress' for update;
 if v_attempt.id is null or not exists(select 1 from public.exam_assessments a join public.exam_programmes p on p.id=a.programme_id where a.id=v_attempt.assessment_id and a.assessment_type='mock' and p.code='CA35P') then raise exception 'Mock attempt not found or already submitted'; end if;
 if now() >= v_attempt.started_at+interval '180 minutes' then raise exception 'Time has expired. Submit the saved draft.'; end if;
 if not exists(select 1 from public.exam_access_grants g join public.exam_assessments a on a.programme_id=g.programme_id where a.id=v_attempt.assessment_id and g.user_id=v_user and g.access_level='full' and g.revoked_at is null and g.starts_at<=now() and (g.expires_at is null or g.expires_at>now())) then raise exception 'Full access is no longer active'; end if;
 if pg_catalog.jsonb_typeof(p_responses)<>'object' or (select count(*) from pg_catalog.jsonb_object_keys(p_responses))>25 then raise exception 'Invalid response set'; end if;
 for v_item in select i.question_id,q.question_type,q.rights_metadata->>'mock_code' as code from public.exam_assessment_items i join public.exam_questions q on q.id=i.question_id where i.assessment_id=v_attempt.assessment_id loop
   if p_responses ? v_item.code then
     v_value:=p_responses->>v_item.code;
     if length(v_value)>5000 then raise exception 'Response too long'; end if;
     if v_item.question_type='single_choice' and v_value not in ('a','b','c','d','') then raise exception 'Invalid choice'; end if;
     insert into public.exam_assessment_responses(attempt_id,question_id,response,answered_at) values(p_attempt_id,v_item.question_id,jsonb_build_object('value',v_value),now()) on conflict(attempt_id,question_id) do update set response=excluded.response,answered_at=now();
     v_saved:=v_saved+1;
   end if;
 end loop;
 if (select count(*) from pg_catalog.jsonb_object_keys(p_responses))<>v_saved then raise exception 'Unknown question code'; end if;
 return v_saved;
end $$;

create or replace function public.submit_ca35p_mock(p_attempt_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_user uuid:=(select auth.uid()); v_attempt public.exam_assessment_attempts%rowtype; v_mc integer; v_core integer; v_special integer; v_missing integer;
begin
 if v_user is null then raise exception 'Sign in required'; end if;
 select * into v_attempt from public.exam_assessment_attempts where id=p_attempt_id and user_id=v_user and status='in_progress' for update;
 if v_attempt.id is null or not exists(select 1 from public.exam_assessments a join public.exam_programmes p on p.id=a.programme_id where a.id=v_attempt.assessment_id and a.assessment_type='mock' and p.code='CA35P') then raise exception 'Mock attempt not found or already submitted'; end if;
 select count(*) into v_missing from public.exam_assessment_items i join public.exam_questions q on q.id=i.question_id left join public.exam_assessment_responses r on r.attempt_id=p_attempt_id and r.question_id=i.question_id where i.assessment_id=v_attempt.assessment_id and (q.rights_metadata->>'mock_code' ~ '^M[0-9]{2}$' or q.rights_metadata->>'mock_code' in ('P1','P2','P3')) and (r.id is null or length(trim(r.response->>'value'))<case when q.question_type='practical' then 250 else 1 end);
 select count(*) into v_special from public.exam_assessment_responses r join public.exam_questions q on q.id=r.question_id where r.attempt_id=p_attempt_id and q.rights_metadata->>'mock_code' in ('S-FIN','S-GOV') and length(trim(r.response->>'value'))>=250;
 if now()<v_attempt.started_at+interval '180 minutes' and (v_missing>0 or v_special<>1) then raise exception 'Complete all 20 questions, three practicals and exactly one specialisation before submission'; end if;
 if now()>=v_attempt.started_at+interval '180 minutes' then
   insert into public.exam_assessment_responses(attempt_id,question_id,response) select p_attempt_id,q.id,jsonb_build_object('value','') from public.exam_assessment_items i join public.exam_questions q on q.id=i.question_id where i.assessment_id=v_attempt.assessment_id and q.rights_metadata->>'mock_code' in ('P1','P2','P3') on conflict(attempt_id,question_id) do nothing;
   if v_special=0 then insert into public.exam_assessment_responses(attempt_id,question_id,response) select p_attempt_id,q.id,jsonb_build_object('value','') from public.exam_assessment_items i join public.exam_questions q on q.id=i.question_id where i.assessment_id=v_attempt.assessment_id and q.rights_metadata->>'mock_code'='S-FIN' on conflict(attempt_id,question_id) do nothing; end if;
 end if;
 update public.exam_assessment_responses r set awarded_points=case when r.response->>'value'=k.answer_key->>'correct_option' then 1 else 0 end,grader_feedback=case when r.response->>'value'=k.answer_key->>'correct_option' then 'Correct' else 'Review the source data and method' end from private.exam_question_keys k, public.exam_questions q where r.attempt_id=p_attempt_id and k.question_id=r.question_id and q.id=r.question_id and q.question_type='single_choice';
 select coalesce(sum(r.awarded_points),0)::integer into v_mc from public.exam_assessment_responses r join public.exam_questions q on q.id=r.question_id where r.attempt_id=p_attempt_id and q.question_type='single_choice';
 update public.exam_assessment_attempts set status='submitted',submitted_at=now(),score=v_mc,percentage=v_mc,integrity_metadata=integrity_metadata || jsonb_build_object('mc_score',v_mc,'expired',now()>=started_at+interval '180 minutes') where id=p_attempt_id;
 return jsonb_build_object('status','submitted','mc_score',v_mc,'practical_pending',true);
end $$;

create or replace function public.review_ca35p_mock(p_attempt_id uuid,p_scores jsonb,p_feedback text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_reviewer uuid:=(select auth.uid()); v_attempt public.exam_assessment_attempts%rowtype; v_item record; v_score integer; v_total integer:=0; v_mc integer; v_count integer:=0;
begin
 if v_reviewer is null then raise exception 'Sign in required'; end if;
 select * into v_attempt from public.exam_assessment_attempts where id=p_attempt_id and status='submitted' for update;
 if v_attempt.id is null or not exists(select 1 from public.exam_assessments a join public.exam_programmes p on p.id=a.programme_id where a.id=v_attempt.assessment_id and a.assessment_type='mock' and p.code='CA35P') then raise exception 'Pending mock attempt not found'; end if;
 if v_attempt.user_id=v_reviewer then raise exception 'A reviewer cannot grade their own attempt'; end if;
 if not exists(select 1 from public.exam_assessment_attempts at join public.exam_assessments a on a.id=at.assessment_id join public.exam_programme_staff s on s.programme_id=a.programme_id and s.user_id=v_reviewer where at.id=p_attempt_id and s.active and s.role in ('reviewer','instructor','administrator')) then raise exception 'Reviewer role required'; end if;
 if length(trim(p_feedback))<30 or length(trim(p_feedback))>3000 or pg_catalog.jsonb_typeof(p_scores)<>'object' then raise exception 'Meaningful feedback and scores required'; end if;
 for v_item in select r.id,q.rights_metadata->>'mock_code' as code from public.exam_assessment_responses r join public.exam_questions q on q.id=r.question_id where r.attempt_id=p_attempt_id and q.question_type='practical' and (q.rights_metadata->>'mock_code' in ('P1','P2','P3') or (q.rights_metadata->>'mock_code' in ('S-FIN','S-GOV') and r.id=(select r2.id from public.exam_assessment_responses r2 join public.exam_questions q2 on q2.id=r2.question_id where r2.attempt_id=p_attempt_id and q2.rights_metadata->>'mock_code' in ('S-FIN','S-GOV') order by case when length(trim(r2.response->>'value'))>0 then 0 else 1 end, q2.rights_metadata->>'mock_code' limit 1))) loop
   if not (p_scores ? v_item.code) or (p_scores->>v_item.code) !~ '^(0|[1-9]|1[0-9]|20)$' then raise exception 'Every submitted practical needs a score from 0 to 20'; end if;
   v_score:=(p_scores->>v_item.code)::integer;
   update public.exam_assessment_responses set awarded_points=v_score,grader_feedback=trim(p_feedback),graded_by=v_reviewer where id=v_item.id;
   v_total:=v_total+v_score;v_count:=v_count+1;
 end loop;
 if v_count<>4 or (select count(*) from pg_catalog.jsonb_object_keys(p_scores))<>4 then raise exception 'Exactly four practical scores required'; end if;
 v_mc:=coalesce((v_attempt.integrity_metadata->>'mc_score')::integer,0);
 update public.exam_assessment_attempts set status='graded',graded_at=now(),score=v_mc+v_total,percentage=v_mc+v_total,passed=v_mc+v_total>=(select pass_mark from public.exam_assessments where id=v_attempt.assessment_id),integrity_metadata=integrity_metadata || jsonb_build_object('reviewed_by',v_reviewer,'practical_score',v_total,'reviewer_feedback',trim(p_feedback)) where id=p_attempt_id;
 return jsonb_build_object('score',v_mc+v_total,'passed',v_mc+v_total>=(select pass_mark from public.exam_assessments where id=v_attempt.assessment_id));
end $$;

revoke all on function public.start_ca35p_mock() from public,anon;
revoke all on function public.save_ca35p_mock(uuid,jsonb) from public,anon;
revoke all on function public.submit_ca35p_mock(uuid) from public,anon;
revoke all on function public.review_ca35p_mock(uuid,jsonb,text) from public,anon;
grant execute on function public.start_ca35p_mock() to authenticated;
grant execute on function public.save_ca35p_mock(uuid,jsonb) to authenticated;
grant execute on function public.submit_ca35p_mock(uuid) to authenticated;
grant execute on function public.review_ca35p_mock(uuid,jsonb,text) to authenticated;
